456	fn leader_completes(combos: &[KeyCombo], leader: &ChordLeader, code: u16) -> Option<usize> {
457	    leader.candidates.iter().copied().find(|&index| {
458	        let keys = &combos[index].keys;
459	        keys.iter()
460	            .all(|key| *key == code || leader.seen.contains(key))
461	    })
462	}
