464	fn leader_still_possible(combos: &[KeyCombo], leader: &ChordLeader, code: u16) -> bool {
465	    leader
466	        .candidates
467	        .iter()
468	        .any(|&index| combos[index].keys.iter().any(|key| *key == code))
