    pub shield_key: KeySet,
    /// 「唤醒视角」热键(空 = 未绑定)。
    ///
    /// 真机定性(2026-10-11):锁死时我们的通道与进程都活着,而**鼠标点不了任何
    /// 界面**(隔膜/卡死那类),唯一还通的路是键盘 —— 用户按 F8(关映射 →
    /// `release_all` 抬掉全部触点)能立刻恢复。两种恢复手段唯一共同的动作就是
    /// **把我们按着的那根瞄准指抬起来**。这个键就把那一下单独摘出来:
    /// 按一次 → 抬起瞄准指,**不关映射、不退出 FPS**;下一次鼠标位移会自动重新落指
    /// (`aim_lift` 已清空偏移与计时,见它的实现)。
    ///
    /// 与 [`Self::shield_key`] 的区别:那个键翻转"鼠标独占"的手动开关,这个键
    /// **只抬指、一下就好**。默认未绑定 = 行为与从前逐位一致(不许改默认手感)。
    #[serde(default)]
    pub wake_key: KeySet,
    /// 「强制重连控制通道」热键(空 = 未绑定)。
    ///
    /// 备用逃生门:锁死时若"抬指"救不回来,说明坏的可能是我们这条 control-only
    /// 通道(server 的进程与 socket 都还在,设备端读线程却已经死了 —— 存活自检
    /// 抓不到这一半)。按一下等同诊断面板里的[强制重连控制通道]:**只重启我们
    /// 自己的控制通道,不动 scrcpy 投屏**;按键处理在界面侧(工作线程 + 请求),
    /// 不在持锁状态里做 adb/网络。
    ///
    /// 默认未绑定 = 行为与从前逐位一致。
    #[serde(default)]
    pub reconnect_key: KeySet,
    /// 压枪/后坐力补偿(V2-1)。默认全关;参数语义对齐 K2er《鼠标宏》专页。
    #[serde(default)]
    pub recoil: Recoil,
}"}

